package com.lynx.ad.modules.agentops.application;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.fasterxml.jackson.databind.*;
import com.lynx.ad.common.domain.Ids.*;
import com.lynx.ad.common.exception.BizException;
import com.lynx.ad.modules.agentops.infrastructure.*;
import com.lynx.ad.modules.agentops.infrastructure.OptimizationAutomationStore.Event;
import com.lynx.ad.modules.delivery.application.PlanInsightsService;
import com.lynx.ad.modules.delivery.domain.model.AdPlan;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;

class OptimizationExecutionTest {
    static final ObjectMapper json=new ObjectMapper();static final ZoneId zone=ZoneId.of("Asia/Shanghai");
    final Instant now=Instant.now();final OptimizationStore store=mock(OptimizationStore.class);final OptimizationAutomationStore journal=mock(OptimizationAutomationStore.class);
    final OptimizationExecutionGateway gateway=mock(OptimizationExecutionGateway.class);final PlanInsightsService insights=mock(PlanInsightsService.class);final AdPlan plan=mock(AdPlan.class);
    final OptimizationExecutionService service=new OptimizationExecutionService(store,journal,gateway,insights);
    JsonNode facts;OptimizationStore.State state;Event event;
    OptimizationPolicy config(String mode){return new OptimizationPolicy(true,mode,new BigDecimal("500"),new BigDecimal("200"),new BigDecimal("100"),3,3,60,List.of(new OptimizationPolicy.Economics("p1",new BigDecimal(".4"),BigDecimal.ZERO,true)));}
    JsonNode report(){var r=json.createObjectNode();r.put("observed_at",now.atZone(zone).toOffsetDateTime().toString()).put("plan_id","123").put("store_id","t").put("account_id","a").put("state","READY").put("window_count",3).put("window_end",now.atZone(zone).minusMinutes(60).withMinute(0).withSecond(0).withNano(0).toOffsetDateTime().toString()).put("estimated_contribution_profit","132.00").put("orders","15").put("spend","300.00").put("net_revenue","1080.00").put("break_even_net_roi","2.78");return r;}
    Event event(String kind,String cause,String expected,String target,String status){var a=json.createObjectNode().put("kind",kind).put("cause",cause).put("expected",expected).put("target",target);return new Event("event","t","p","a","plan",1,kind,"建议","依据",a,report(),status,null,null,now,Set.of("EXECUTING","VERIFY_PENDING").contains(status)?now.minusSeconds(200):null,null);}
    OptimizationStore.State state(OptimizationPolicy policy,String hold,Instant action,String reason,Instant paused){return new OptimizationStore.State("t","p",1,true,policy,null,now,null,report(),hold,facts,action,reason,paused);}
    @BeforeEach void setup(){facts=json.createObjectNode().put("qcId","123").put("status","DELIVERING").put("budget","400").put("roi","1.6").put("bidType","CUSTOM");((com.fasterxml.jackson.databind.node.ObjectNode)facts).putArray("productIds").add("p1");state=state(config("AUTO_LIMITED"),null,null,null,null);event=event("BUDGET","PERSISTENT_PROFIT","400","440","READY");
        when(plan.tenantId()).thenReturn(new TenantId("t"));when(plan.id()).thenReturn(new PlanId("p"));when(plan.accountId()).thenReturn(new AccountId("a"));when(gateway.plan("t","p")).thenReturn(plan);when(gateway.facts(plan)).thenReturn(facts);when(gateway.related(plan)).thenReturn(List.of("p"));when(store.get(new TenantId("t"),new PlanId("p"))).thenReturn(Optional.of(state));when(store.economics(plan)).thenReturn(config("AUTO_LIMITED").economics());when(journal.claimAccount(eq("t"),eq("a"),anyString())).thenReturn(true);when(journal.event("t","event")).thenReturn(Optional.of(event));when(journal.limit("t","a")).thenReturn(new BigDecimal("1000"));when(gateway.accountBudget(plan)).thenReturn(new BigDecimal("400"));when(insights.data(any(),any(),any(),eq(true))).thenReturn(new PlanInsightsService.Statistics(Map.of("cost",new BigDecimal("100")),List.of(),"stat_time_hour",now,null));}
    @Test void approvedBoundedBudgetPasses(){assertDoesNotThrow(()->OptimizationExecutionService.validate(state,event,facts,now,0));}
    @Test void automaticCostBudgetCanReach100ButCannotCrossThePlatformFloor() {
        ((com.fasterxml.jackson.databind.node.ObjectNode)facts).put("budget","111");
        var atMinimum=event("BUDGET","PERSISTENT_LOSS","111","100","READY");
        ((com.fasterxml.jackson.databind.node.ObjectNode)atMinimum.report()).put("estimated_contribution_profit","-10");
        assertDoesNotThrow(()->OptimizationExecutionService.validate(state,atMinimum,facts,now,0));
        var belowMinimum=event("BUDGET","PERSISTENT_LOSS","111","99.99","READY");
        ((com.fasterxml.jackson.databind.node.ObjectNode)belowMinimum.report()).put("estimated_contribution_profit","-10");
        assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,belowMinimum,facts,now,0));
    }
    @Test void observationModeNeverWrites(){assertThrows(BizException.class,()->OptimizationExecutionService.validate(state(config("OBSERVE"),null,null,null,null),event,facts,now,0));}
    @Test void staleOrNextDayAdviceNeverWrites(){assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,event,facts,now.plusSeconds(601),0));assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,event,facts,now.plus(Duration.ofDays(1)),0));}
    @Test void excessiveStepAndChangedRemoteValueNeverWrite(){assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,event("BUDGET","PERSISTENT_PROFIT","400","500","READY"),facts,now,0));((com.fasterxml.jackson.databind.node.ObjectNode)facts).put("budget","410");assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,event,facts,now,0));}
    @Test void cooldownAndDailyLimitBlockExpansion(){assertThrows(BizException.class,()->OptimizationExecutionService.validate(state(config("AUTO_LIMITED"),null,now.minusSeconds(60),null,null),event,facts,now,0));assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,event,facts,now,3));}
    @Test void riskPauseBypassesExpansionCooldown(){var pause=event("PAUSE","DAILY_LIMIT","DELIVERING","PAUSED","READY");assertDoesNotThrow(()->OptimizationExecutionService.validate(state(config("AUTO_LIMITED"),null,now.minusSeconds(60),null,null),pause,facts,now,10));}
    @Test void manualOrLossPauseNeverAutoResumes(){((com.fasterxml.jackson.databind.node.ObjectNode)facts).put("status","PAUSED");var resume=event("ENABLE","NEXT_DAY","PAUSED","DELIVERING","READY");assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,resume,facts,now,0));assertThrows(BizException.class,()->OptimizationExecutionService.validate(state(config("AUTO_LIMITED"),null,null,"LOSS",now.minus(Duration.ofDays(1))),resume,facts,now,0));}
    @Test void accountCeilingBlocksRealWrite(){when(journal.limit("t","a")).thenReturn(new BigDecimal("430"));service.process(event);verify(gateway,never()).write(any(),any());verify(journal,never()).dispatch(any(),anyString());verify(journal).finish(eq(event),eq("SKIPPED"),contains("账户总日预算"),isNull());}
    @Test void missingCeilingBlocksExpansion(){when(journal.limit("t","a")).thenReturn(null);service.process(event);verify(gateway,never()).write(any(),any());}
    @Test void unverifiedEconomicsBlocksRealWrite(){when(store.economics(plan)).thenReturn(List.of());service.process(event);verify(gateway,never()).write(any(),any());}
    @Test void successfulWriteIsJournaledBeforePlatformCallAndReadBack(){var after=facts.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)after).put("budget","440");when(gateway.facts(plan)).thenReturn(facts,after);when(journal.dispatch(eq(event),anyString())).thenReturn(true);service.process(event);var order=inOrder(journal,gateway);order.verify(journal).dispatch(eq(event),anyString());order.verify(gateway).write(plan,event.proposal());order.verify(gateway).facts(plan);order.verify(journal).succeeded(event,after);}
    @Test void submittedTimeoutOnlyRechecksAfterRestart(){when(journal.dispatch(eq(event),anyString())).thenReturn(true);doThrow(new RuntimeException("network")).when(gateway).write(any(),any());service.process(event);verify(journal).finish(eq(event),eq("VERIFY_PENDING"),contains("不会重复提交"),isNull());clearInvocations(gateway,journal);var retry=event("BUDGET","PERSISTENT_PROFIT","400","440","EXECUTING");when(journal.event("t","event")).thenReturn(Optional.of(retry));service.process(retry);verify(gateway,never()).write(any(),any());verify(journal,never()).dispatch(any(),anyString());verify(journal).finish(eq(retry),eq("UNKNOWN"),anyString(),eq(facts));}
    @Test void accountLeaseConflictAndUnresolvedReceiptNeverWrite(){when(journal.claimAccount(anyString(),anyString(),anyString())).thenReturn(false);service.process(event);verifyNoInteractions(gateway);when(journal.claimAccount(anyString(),anyString(),anyString())).thenReturn(true);when(journal.unresolved("t","a")).thenReturn(true);service.process(event);verify(gateway,never()).write(any(),any());}
    @Test void externalManualChangePausesAuthorization(){var changed=facts.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)changed).put("budget","450");service.observe(plan,state,changed);verify(journal).hold(eq("t"),eq(List.of("p")),contains("人工变更"));}
    @Test void heldAuthorizationAndUnknownActionsRejected(){assertThrows(BizException.class,()->OptimizationExecutionService.validate(state(config("AUTO_LIMITED"),"manual",null,null,null),event,facts,now,0));assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,event("SEARCH","whatever","400","500","READY"),facts,now,0));}
    @Test void queuedLegacyProductAdditionIsSkippedWithoutDispatch(){var old=event("PRODUCT_ADD","PROFITABLE_CANDIDATE","400","440","READY");when(journal.event("t","event")).thenReturn(Optional.of(old));service.process(old);verify(journal,never()).dispatch(any(),anyString());verify(gateway,never()).write(any(),any());verify(journal).finish(eq(old),eq("SKIPPED"),contains("不支持"),isNull());}
    @Test void dispatchedLegacyProductAdditionCanOnlyBeReadBack(){var tactics=mock(OptimizationTacticsGateway.class);when(gateway.tactics()).thenReturn(tactics);var actual=json.createObjectNode();var intent=actual.putObject("operation").put("productId","p2");var action=json.createObjectNode().put("kind","PRODUCT_ADD").put("cause","PROFITABLE_CANDIDATE").put("entity_id","p2").put("product_id","p2");var old=new Event("event","t","p","a","plan",1,"PRODUCT_ADD","历史新增","依据",action,report(),"EXECUTING",null,actual,now,now.minusSeconds(200),null);when(journal.event("t","event")).thenReturn(Optional.of(old));when(tactics.matches(plan,action,intent)).thenReturn(true);service.process(old);verify(tactics,never()).prepare(any(),any(),any(),anyString());verify(tactics,never()).write(any(),any(),any());verify(gateway,never()).write(any(),any());verify(journal).succeeded(eq(old),argThat(n->n.path("actionConfirmed").asBoolean()));}
    @Test void currentReportHidesLegacyProductAddWithoutChangingAuditSource(){var old=report();var list=((com.fasterxml.jackson.databind.node.ObjectNode)old).putArray("recommendations");list.addObject().put("type","PRODUCT_ADD_REVIEW").putObject("action").put("kind","PRODUCT_ADD");list.addObject().put("type","PRODUCT_REMOVE_REVIEW").putObject("action").put("kind","PRODUCT_REMOVE");var current=new OptimizationStore.State("t","p",1,true,config("AUTO_LIMITED"),null,now,null,old);assertEquals(1,current.result().path("recommendations").size());assertEquals("PRODUCT_REMOVE",current.result().path("recommendations").get(0).path("action").path("kind").asText());assertEquals(2,old.path("recommendations").size());}
    OptimizationPolicy roiAndResume(){var p=config("AUTO_LIMITED");var a=new OptimizationPolicy.Automation(true,true,true,true,new BigDecimal("300"),new BigDecimal("500"),new BigDecimal(".01"),new BigDecimal("100"),BigDecimal.TEN,120,3,0);return new OptimizationPolicy(true,p.mode(),p.dailySpendLimit(),p.maxLoss(),p.minSpend(),3,3,60,p.economics(),a);}
    @Test void roiLossAdjustmentRequiresExplicitPermissionAndCorrectDirection(){var e=event("ROI","PERSISTENT_LOSS","1.6","1.76","READY");((com.fasterxml.jackson.databind.node.ObjectNode)e.report()).put("estimated_contribution_profit","-80.00");assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,e,facts,now,0));assertDoesNotThrow(()->OptimizationExecutionService.validate(state(roiAndResume(),null,null,null,null),e,facts,now,0));}
    @Test void roiDecreaseCannotCrossBreakEvenProtection(){((com.fasterxml.jackson.databind.node.ObjectNode)facts).put("roi","4");var e=event("ROI","PROFITABLE_LOW_DELIVERY","4","3.6","READY");assertDoesNotThrow(()->OptimizationExecutionService.validate(state(roiAndResume(),null,null,null,null),e,facts,now,0));((com.fasterxml.jackson.databind.node.ObjectNode)facts).put("roi","3.3");var below=event("ROI","PROFITABLE_LOW_DELIVERY","3.3","3.0","READY");assertThrows(BizException.class,()->OptimizationExecutionService.validate(state(roiAndResume(),null,null,null,null),below,facts,now,0));}
    @Test void onlyAuthorizedOwnPriorDailyPauseCanRestart(){((com.fasterxml.jackson.databind.node.ObjectNode)facts).put("status","PAUSED");var e=event("ENABLE","NEXT_DAY","PAUSED","DELIVERING","READY");assertDoesNotThrow(()->OptimizationExecutionService.validate(state(roiAndResume(),null,null,"DAILY_LIMIT",now.minus(Duration.ofDays(1))),e,facts,now,0));assertThrows(BizException.class,()->OptimizationExecutionService.validate(state(roiAndResume(),null,null,"DAILY_LIMIT",now),e,facts,now,0));}
    @Test void transferPeerRunningBlocksAutomaticEnableBeforeDispatch(){((com.fasterxml.jackson.databind.node.ObjectNode)facts).put("status","PAUSED");var e=event("ENABLE","NEXT_DAY","PAUSED","DELIVERING","READY");var s=state(roiAndResume(),null,null,"DAILY_LIMIT",now.minus(Duration.ofDays(1)));when(store.get(any(),any())).thenReturn(Optional.of(s));when(journal.event("t","event")).thenReturn(Optional.of(e));doThrow(new BizException(1803,"关联转投计划仍在运行")).when(gateway).assertPeerStopped(plan);service.process(e);verify(gateway,never()).write(any(),any());verify(journal,never()).dispatch(any(),anyString());}
    @Test void malformedPauseTargetCannotBeDispatched(){var wrong=event("PAUSE","DAILY_LIMIT","DELIVERING","DELIVERING","READY");assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,wrong,facts,now,0));}
    @Test void insufficientOrdersOrProfitRateNeverScale(){((com.fasterxml.jackson.databind.node.ObjectNode)event.report()).put("orders","0");assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,event,facts,now,0));((com.fasterxml.jackson.databind.node.ObjectNode)event.report()).put("orders","15").put("estimated_contribution_profit","1.00");assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,event,facts,now,0));}
    OptimizationPolicy boostPolicy(){var p=config("AUTO_LIMITED");var t=new OptimizationPolicy.Tactics(true,false,false,false,false,false,new BigDecimal("100"),BigDecimal.ONE,new BigDecimal("300"),2,1,1,List.of());return new OptimizationPolicy(true,p.mode(),p.dailySpendLimit(),p.maxLoss(),p.minSpend(),3,3,60,p.economics(),p.automation(),t);}
    Event boostEvent(String status,JsonNode actual){var action=json.createObjectNode().put("kind","BOOST").put("cause","PERSISTENT_PROFIT").put("budget","100").put("duration","1");return new Event("event","t","p","a","plan",1,"BOOST","自动一键起量","盈利",action,report(),status,null,actual,now,status.equals("READY")?null:now.minusSeconds(200),null);}
    @Test void automaticBoostPersistsIntentBeforeWritingAndVerifiesResult(){var e=boostEvent("READY",null);var tactics=mock(OptimizationTacticsGateway.class);when(gateway.tactics()).thenReturn(tactics);var prepared=new OptimizationTacticsGateway.Prepared(List.of(),null,"","task","SMART_BOOST");var intent=json.createObjectNode().put("taskName","task").put("scene","SMART_BOOST");when(tactics.prepare(eq(plan),any(),eq(e.proposal()),eq("event"))).thenReturn(prepared);when(tactics.intent(prepared)).thenReturn(intent);when(tactics.matches(plan,e.proposal(),intent)).thenReturn(true);when(gateway.activeTaskBudget(plan)).thenReturn(BigDecimal.ZERO);when(gateway.facts(plan)).thenAnswer(inv->facts.deepCopy());when(journal.event("t","event")).thenReturn(Optional.of(e));when(journal.dispatch(eq(e),anyString())).thenReturn(true);when(store.get(any(),any())).thenReturn(Optional.of(state(boostPolicy(),null,null,null,null)));service.process(e);var order=inOrder(journal,tactics);order.verify(journal).dispatch(eq(e),anyString());order.verify(journal).intent(e,intent);order.verify(tactics).write(plan,e.proposal(),prepared);verify(gateway,never()).write(any(),any());verify(journal).succeeded(eq(e),argThat(n->n.path("actionConfirmed").asBoolean()));}
    @Test void restartAfterContentDispatchOnlyReadsAndRetainsIntent(){var tactics=mock(OptimizationTacticsGateway.class);when(gateway.tactics()).thenReturn(tactics);var actual=json.createObjectNode();actual.putObject("operation").put("taskName","task").put("scene","SMART_BOOST");var e=boostEvent("EXECUTING",actual);when(gateway.facts(plan)).thenAnswer(inv->facts.deepCopy());when(journal.event("t","event")).thenReturn(Optional.of(e));service.process(e);verify(tactics,never()).prepare(any(),any(),any(),anyString());verify(tactics,never()).write(any(),any(),any());verify(journal).finish(eq(e),eq("UNKNOWN"),anyString(),argThat(n->n.path("operation").path("taskName").asText().equals("task")));}
    @Test void newActionsAreDisabledUnlessSeparatelyAuthorized(){assertThrows(BizException.class,()->OptimizationExecutionService.validate(state,boostEvent("READY",null),facts,now,0));}
}
